import difflib,subprocess
R=Path.cwd();A=R/'artifacts/crow-v15-heavy-wing-teacher-route-20261110';B=R/'build/crow-v15-heavy-wing-teacher-route-20261110';F=R/'artifacts/crow-v15-flight-feedback-freeze-20261110';old=(R/'build/crow-v15-heavy-wing-route-20261110/route.metal').read_text();needle='const float heightTarget = clamp(target.z+0.30f,1.15f,1.30f);';assert old.count(needle)==1;s=old.replace(needle,'const float heightTarget = clamp(target.z,0.80f,1.15f);');(B/'teacher.metal').write_text(s);(A/'teacher.patch').write_text(''.join(difflib.unified_diff(old.splitlines(True),s.splitlines(True),fromfile='a/route.metal',tofile='b/teacher.metal')));subprocess.run(['xcrun','-sdk','macosx','metal','-std=metal4.0','-O3','-fno-fast-math','-I',str(F),'-I',str(R/'include'),'-I',str(R/'src/metal'),'-c',str(B/'teacher.metal'),'-o',str(B/'teacher.air')],check=True);other=sorted(p for p in (R/'build/shaders').glob('MetalRobo*.air') if p.name not in ('MetalRoboLocomotionTask.air','MetalRoboFlappingWingDynamics.air'));subprocess.run(['xcrun','-sdk','macosx','metallib',*[str(x) for x in other],str(R/'build/crow-v15-wing-aero-alignment-20261110/aero.air'),str(B/'teacher.air'),'-o',str(B/'teacher.metallib')],check=True)
